import React from 'react';
import SalesChart from './Analytics/SalesChart';
import TrafficChart from './Analytics/TrafficChart';

const AnalyticsPage = () => {
  return (
    <>
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-neutral-900 dark:text-white">Analytique et rapports</h1>
        <p className="text-neutral-600 dark:text-neutral-400">Analyses détaillées de vos performances</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
        <SalesChart />
        <TrafficChart />
      </div>
    </>
  );
};

export default AnalyticsPage;
